using System.Buffers;using PogoInventory.Streaming;using PogoInventory.Streaming.Scrcpy;
var tests=new(string,Action)[]{("ROI validates and maps rows",Roi),("read-only API has no input methods",ReadOnly),("normalized region rejects overflow",Invalid)};int fail=0;foreach(var t in tests)try{t.Item2();Console.WriteLine("PASS "+t.Item1);}catch(Exception e){fail++;Console.Error.WriteLine("FAIL "+t.Item1+": "+e.Message);}return fail;
static void Roi(){var owner=MemoryPool<byte>.Shared.Rent(64);for(int i=0;i<64;i++)owner.Memory.Span[i]=(byte)i;var raw=new RawFrame(owner,64,new(4,4,16,FramePixelFormat.Bgra32),new(1,DateTimeOffset.UtcNow,TimeSpan.Zero),1);var meta=new FrameMetadata(new(1),raw.Timestamp,raw.Descriptor,new(1,1,0,0,1),new(0,3,TimeSpan.FromMilliseconds(100),true),"test");var sf=new SharedFrameAccessor(raw,meta);using var crop=new FrameCropView(sf.Lease(),new(.25,.25,.5,.5));if(crop.GetRow(0)[0]!=20)throw new Exception("wrong ROI offset");}
static void ReadOnly(){var names=typeof(IReadOnlyVideoTransport).Assembly.GetExportedTypes().SelectMany(t=>t.GetMethods()).Select(m=>m.Name).ToArray();var forbidden=new[]{"Tap","Swipe","Clipboard","Home","Back","Scroll","Inject"};if(names.Any(n=>forbidden.Any(f=>n.Contains(f,StringComparison.OrdinalIgnoreCase))))throw new Exception("public control surface detected");}
static void Invalid(){try{new NormalizedRegion(.9,0,.2,.2).Validate();throw new Exception("not rejected");}catch(ArgumentOutOfRangeException){}}
sealed class SharedFrameAccessor:IDisposable{readonly RawFrame _raw;readonly FrameMetadata _m;public SharedFrameAccessor(RawFrame r,FrameMetadata m){_raw=r;_m=m;}public IFrameLease Lease()=>new L(_raw.Pixels,_m);public void Dispose()=>_raw.Dispose();sealed class L(ReadOnlyMemory<byte> p,FrameMetadata m):IFrameLease{public FrameMetadata Metadata=>m;public ReadOnlyMemory<byte> Pixels=>p;public void Dispose(){}}}
